<?php
$n = (int) trim(fgets(STDIN));
$s = trim(fgets(STDIN));
$m = strlen($s);

// prefix function (KMP failure function)
$fail = array_fill(0, $m, 0);
for ($i = 1; $i < $m; $i++) {
    $k = $fail[$i - 1];
    while ($k > 0 && $s[$i] != $s[$k]) {
        $k = $fail[$k - 1];
    }
    if ($s[$i] == $s[$k]) {
        $k++;
    }
    $fail[$i] = $k;
}

function getNext($state, $bit, $s, $fail) {
    while ($state > 0 && $s[$state] != $bit) {
        $state = $fail[$state - 1];
    }
    if ($s[$state] == $bit) {
        $state++;
    }
    return $state;
}

$trans = array();
for ($q = 0; $q < $m; $q++) {
    foreach (array('0', '1') as $bit) {
        $trans[$q][$bit] = getNext($q, $bit, $s, $fail);
    }
}

$total = 1 << $n; // n <= 40, fits within PHP int (64-bit)

$avoid = 0;
for ($q0 = 0; $q0 < $m; $q0++) {
    $dp = array_fill(0, $m, 0);
    $dp[$q0] = 1;
    for ($step = 0; $step < $n; $step++) {
        $ndp = array_fill(0, $m, 0);
        for ($s2 = 0; $s2 < $m; $s2++) {
            if ($dp[$s2] == 0) continue;
            foreach (array('0', '1') as $bit) {
                $ns = $trans[$s2][$bit];
                if ($ns < $m) {
                    $ndp[$ns] += $dp[$s2];
                }
            }
        }
        $dp = $ndp;
    }
    $avoid += $dp[$q0];
}

echo ($total - $avoid) . "\n";
?>
